  function variables(){const prior=state.variable;let options=catalog.filter(x=>x.provider===state.provider);if(state.provider==='power-daily')options=catalog.filter(x=>x.provider==='power');if(['forecast','era5'].includes(state.provider))options=[['temperature_2m','Temperatura'],['precipitation','Precipitación'],['wind_speed_10m','Viento a 10 m'],['wind_gusts_10m','Ráfagas'],['relative_humidity_2m','Humedad'],['apparent_temperature','Sensación térmica'],['cloud_cover','Nubosidad'],['wind_direction_10m','Dirección del viento'],...(state.provider==='forecast'?[['precipitation_probability','Probabilidad de lluvia'],['visibility','Visibilidad']]:[])].map(([variable,name])=>({variable,name}));
    options=options.filter((x,i,a)=>a.findIndex(v=>v.variable===x.variable)===i);$('variable').innerHTML=options.map(x=>`<option value="${escape(x.variable)}">${escape(x.name||x.variable)}</option>`).join('');state.variable=options.some(x=>x.variable===prior)?prior:options[0]?.variable;$('variable').value=state.variable||'';}
