  function activeValue(){if(!record){$('value').textContent='—';$('value-unit').textContent='Sin dato';$('map-value').textContent='Sin datos para la selección';return;}const prefix=state.scale==='yearly'?state.date.slice(0,4):record.frequency==='monthly'?state.date.slice(0,7):record.frequency==='daily'?state.date.slice(0,10):state.date.slice(0,13);const values=record.series.filter(p=>p.date.startsWith(prefix)&&p.value!=null).map(p=>p.value);$('value').textContent=number(values.length?values.reduce((a,b)=>a+b,0)/values.length:null);$('value-unit').textContent=record.unit+(values.length>1?' · media de '+values.length+' muestras':values.length?'':' · sin cobertura en esta fecha');$('map-value').textContent=state.date.replace('T',' · ')+' UTC · '+$('value').textContent+' '+$('value-unit').textContent;}
  function plot(rows){if(chart)chart.destroy();if(!rows.some(r=>r.series.length)){return;}const anomaly=$('mode').value==='anomaly';const data=rows.map((r,index)=>{let points=r.series;if(anomaly&&r.frequency==='monthly'){const means={};for(let m=1;m<=12;m++){const v=points.filter(p=>+p.date.slice(5,7)===m&&p.value!=null).map(p=>p.value);means[m]=v.length?v.reduce((a,b)=>a+b)/v.length:null;}points=points.map(p=>({...p,value:p.value==null||means[+p.date.slice(5,7)]==null?null:p.value-means[+p.date.slice(5,7)]}));}
    return {label:(r.location?.name||state.city_id)+' · '+r.unit+(anomaly?' · anomalía respecto de la media mensual del rango':''),data:points.map(p=>({x:Date.parse(p.date.length===10?p.date+'T12:00:00Z':p.date),y:p.value})),borderColor:index?'#e5bb7b':'#65d4bd',backgroundColor:'#65d4bd',borderDash:r.kind==='forecast'?[6,4]:[],pointRadius:points.length>100?0:2,spanGaps:false,tension:0};});
    chart=new Chart($('chart'),{type:'line',data:{datasets:data},options:{responsive:true,maintainAspectRatio:false,parsing:false,scales:{x:{type:'linear',min:Math.min(...data.flatMap(d=>d.data.map(p=>p.x))),max:Math.max(...data.flatMap(d=>d.data.map(p=>p.x))),ticks:{maxTicksLimit:5,callback:v=>new Date(v).toISOString().slice(0,record?.frequency==='hourly'?16:10)}},y:{ticks:{color:'#8fa9b9'}}},plugins:{legend:{labels:{color:document.body.classList.contains('light')?'#183042':'#b6c9d5',font:{size:10}}},tooltip:{callbacks:{title:items=>new Date(items[0].parsed.x).toISOString()}}}}});}
  async function obtain(id,signal){if(['forecast','era5','power-daily'].includes(state.provider)){const kind=state.provider==='forecast'?'forecast':state.provider==='era5'?'reanalysis':'power-daily';return api('/api/weather?'+new URLSearchParams({city_id:id,kind,variable:state.variable,start:state.start,end:state.end}),{signal});}return api('/api/workspace/series?'+new URLSearchParams({city_id:id,variable:state.variable,provider:state.provider,start:state.start,end:state.end}),{signal});}
  async function load(){controller?.abort();controller=new AbortController();const ticket=++seq;record=null;comparisonRecords=[];activeValue();if(chart){chart.destroy();chart=null;}$('provenance').innerHTML='';$('comparison').textContent='';notice('Consultando datos y cobertura…');try{const result=await obtain(state.city_id,controller.signal);if(ticket!==seq)return;record=result;const rows=[result];if(['compare','periods'].includes($('mode').value)){
      if($('mode').value==='compare'){for(const c of selectedCities().filter(c=>c.id!==state.city_id).slice(0,4)){try{const other=await obtain(c.id,controller.signal);if(other.unit===result.unit&&other.product===result.product)rows.push(other);}catch(e){if(e.name==='AbortError')throw e;}}}
      else{const midpoint=Date.parse(state.start)+(Date.parse(state.end)-Date.parse(state.start))/2;rows.splice(0,1,{...result,location:{name:'Primera época'},series:result.series.filter(p=>Date.parse(p.date)<midpoint)},{...result,location:{name:'Segunda época'},series:result.series.filter(p=>Date.parse(p.date)>=midpoint)});$('comparison').textContent='Comparación descriptiva de épocas. Las pruebas del motor están en el Laboratorio.';}}
    if(ticket!==seq)return;comparisonRecords=$('mode').value==='compare'?rows:[];for(const option of $('scale').options)option.disabled=(option.value==='hourly'&&result.frequency!=='hourly')||(option.value==='daily'&&!['hourly','daily'].includes(result.frequency));if($('scale').selectedOptions[0]?.disabled){state.scale=result.frequency==='daily'?'daily':'monthly';$('scale').value=state.scale;}plot(rows);$('data-kind').textContent=result.kind==='forecast'?'◇ PRONÓSTICO OPERATIVO':result.kind==='reanalysis'?'● REANÁLISIS':'● HISTÓRICO DE GRILLA';$('data-title').textContent=state.variable;$('provenance').innerHTML=[['Fuente / producto',result.provider+' · '+result.product],['Frecuencia',result.frequency],['Resolución espacial',JSON.stringify(result.spatial_resolution)],['Obtención',result.fetched_at],['Emisión',result.issued_at||'No informada / no aplica'],['Cobertura',result.series.length+' registros; '+(result.quality?.missing??result.coverage?.missing_count??0)+' nulos'],['Licencia',result.license?.description||'Consultar catálogo de fuentes']].map(([k,v])=>`<dt>${escape(k)}</dt><dd>${escape(v)}</dd>`).join('');$('limits').textContent=(result.limitations||[]).join(' ');activeValue();notice(result.series.length?'Datos disponibles. Seleccioná una fecha para inspeccionar su cobertura.':'Sin datos en el intervalo seleccionado.');if($('mode').value==='trend'){
 if(state.provider==='power'){try{const stats=await api('/api/workspace/trends?'+new URLSearchParams({city_id:state.city_id,variable:state.variable,start:state.start,end:state.end}),{signal:controller.signal});if(ticket!==seq)return;$('comparison').innerHTML='<article class="card"><strong>Tendencia exploratoria provisional</strong><p>Cambio por decada: '+number(stats.statistics.change_per_decade)+' '+escape(record.unit)+'</p><p>p nominal: '+escape(stats.statistics.p_value)+'</p><p class="hint">Sin ajustes de autocorrelacion o comparaciones multiples. No es un descubrimiento confirmado ni causal.</p></article>';}catch(e){if(e.name==='AbortError')throw e;$('comparison').textContent=e.message;}}
 else $('comparison').textContent='Tendencias habilitadas solo para seis variables POWER. Serie nativa sin regresion alternativa.';
 }await renderIncidents();}
    catch(e){if(ticket!==seq||e.name==='AbortError')return;notice(e.message,true);$('limits').textContent='Sin cobertura verificada. No se generan valores de respaldo.';
      if(state.provider==='forecast'){try{const climate=await api('/api/workspace/climatology?'+new URLSearchParams({city_id:state.city_id,date:state.date.slice(0,10)}),{signal:controller.signal});if(ticket!==seq)return;$('data-kind').textContent='▱ CLIMATOLOGÍA · NO ES PRONÓSTICO';$('data-title').textContent='Referencia mensual 2000–2024';$('comparison').innerHTML='<p>Fuera del horizonte operativo. Condiciones históricamente habituales para el mes '+climate.month+':</p>'+Object.entries(climate.variables).map(([k,v])=>'<p>'+escape(k)+': '+number(v.mean)+' '+escape(v.unit)+' · '+v.count+' años</p>').join('')+'<p class="hint">'+climate.limitations.map(escape).join(' ')+'</p>';}catch(_){} }
    }}
  function range(){state.start=$('start').value;state.end=$('end').value;if(!state.start||state.start>state.end){notice('El inicio debe ser anterior al fin.',true);return;}$('time-start').textContent=state.start;$('time-end').textContent=state.end;updateTime();safe(load)();}
  function step(direction){const d=new Date(state.date.length===10?state.date+'T12:00:00Z':state.date+'Z');if(state.scale==='yearly')d.setUTCFullYear(d.getUTCFullYear()+direction);else if(state.scale==='monthly')d.setUTCMonth(d.getUTCMonth()+direction);else if(state.scale==='daily')d.setUTCDate(d.getUTCDate()+direction);else d.setUTCHours(d.getUTCHours()+direction);if(d>Date.parse(state.end+'T23:59:59Z')||d<Date.parse(state.start)){stop();return;}updateTime(d.toISOString().slice(0,16));}
  function stop(){clearInterval(timer);timer=null;$('play').textContent='Reproducir';}
  $('play').onclick=()=>{if(timer){stop();return;}$('play').textContent='Pausar';timer=setInterval(()=>step(1),+$('speed').value);};$('speed').onchange=()=>{if(timer){stop();$('play').click();}};
  $('step-back').onclick=()=>step(-1);$('step-next').onclick=()=>step(1);$('date').onchange=()=>{updateTime($('date').value);if($('mode').value==='date'||state.provider==='forecast'){state.start=state.end=state.date.slice(0,10);$('start').value=state.start;$('end').value=state.end;range();}};$('scrubber').oninput=()=>{const min=Date.parse(state.start),max=Date.parse(state.end+'T23:59:59Z');updateTime(new Date(min+(max-min)*+$('scrubber').value/1000).toISOString().slice(0,16));};
