  $('zoom-in').onclick=()=>zoom(.5);$('zoom-out').onclick=()=>zoom(2);
  $('present').onclick=()=>{const now=new Date();state.provider='forecast';$('source').value='forecast';state.scale='hourly';$('scale').value='hourly';state.start=now.toISOString().slice(0,10);state.end=new Date(+now+6*86400000).toISOString().slice(0,10);$('start').value=state.start;$('end').value=state.end;variables();updateTime(now.toISOString().slice(0,16));range();panel('data');};
  $('city').onchange=()=>selectCity($('city').value);$('search').oninput=()=>{const q=$('search').value.toLocaleLowerCase('es');$('city').innerHTML=cities.filter(c=>(c.name+' '+c.province).toLocaleLowerCase('es').includes(q)).map(c=>`<option value="${c.id}">${escape(c.name)}</option>`).join('');if([...$('city').options].some(o=>o.value===state.city_id))$('city').value=state.city_id;};
  $('source').onchange=()=>{state.provider=$('source').value;variables();if(state.provider==='forecast'){$('present').click();}else{state.scale=['era5'].includes(state.provider)?'hourly':state.provider==='power-daily'?'daily':'monthly';$('scale').value=state.scale;safe(load)();}};$('variable').onchange=()=>{state.variable=$('variable').value;queryContext();safe(load)();};$('mode').onchange=safe(load);$('incident-layer').onchange=()=>{$('incidents').hidden=!$('incident-layer').checked;renderEvents();};$('territory').onchange=()=>{state.selected=[state.city_id];renderMap();$('territory-controls').textContent=$('territory').value==='multi'?'Elegí puntos del mapa.':$('territory').value==='polygon'?'Dibujá vértices y completá con doble clic.':'La provincia/región corresponde a la ciudad seleccionada.';};
  function inside(p,points){let yes=false;for(let i=0,j=points.length-1;i<points.length;j=i++){const a=points[i],b=points[j];if((a.lng>p.longitude)!==(b.lng>p.longitude)&&p.latitude<(b.lat-a.lat)*(p.longitude-a.lng)/(b.lng-a.lng)+a.lat)yes=!yes;}return yes;}
  $('draw').onclick=()=>{drawing=true;vertices=[];$('territory').value='polygon';map.doubleClickZoom.disable();notice('Marcá vértices; doble clic para cerrar. Selecciona ciudades, no valida territorio argentino.');};map.on('click',e=>{if(!drawing)return;vertices.push(e.latlng);if(polygon)map.removeLayer(polygon);polygon=L.polygon(vertices,{color:'#65d4bd',fillOpacity:.07}).addTo(map);});map.on('dblclick',()=>{if(!drawing||vertices.length<3)return;drawing=false;map.doubleClickZoom.enable();state.selected=cities.filter(c=>inside(c,vertices)).map(c=>c.id);renderMap();});$('clear-draw').onclick=()=>{if(polygon)map.removeLayer(polygon);polygon=null;drawing=false;state.selected=[];renderMap();};
  function calendar(){const view=$('cal-view').value;const first=new Date(calendarDate);first.setUTCDate(1);let days=view==='month'?new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate():view==='week'?7:1;if(view==='week')first.setUTCDate(calendarDate.getUTCDate()-((calendarDate.getUTCDay()+6)%7));if(view==='day')first.setUTCDate(calendarDate.getUTCDate());$('cal-title').textContent=calendarDate.toLocaleDateString('es-AR',{month:'long',year:'numeric',timeZone:'UTC'});$('calendar').classList.toggle('list',view==='list'||view==='day');if(view==='list'){$('calendar').innerHTML=events.filter(e=>e.status==='active').map(e=>`<button data-day="${escape(e.start.slice(0,10))}">${escape(e.name)} · ${escape(e.start)}</button>`).join('')||'<p>Sin próximos eventos guardados.</p>';}else{let html=view==='month'?'<span></span>'.repeat((first.getUTCDay()+6)%7):'';for(let i=0;i<days;i++){const d=new Date(first);d.setUTCDate(first.getUTCDate()+i);const iso=d.toISOString().slice(0,10);html+=`<button data-day="${iso}" class="${iso===state.date.slice(0,10)?'selected ':''}${events.some(e=>e.start.startsWith(iso))?'has-event':''}">${d.getUTCDate()}</button>`;}$('calendar').innerHTML=html;}$('calendar').querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{updateTime(b.dataset.day);if(state.provider==='forecast'){state.start=state.end=b.dataset.day;$('start').value=state.start;$('end').value=state.end;range();}prepareEvent();});}
  $('cal-view').onchange=calendar;function moveCalendar(direction){const view=$('cal-view').value;if(view==='month'||view==='list')calendarDate.setUTCMonth(calendarDate.getUTCMonth()+direction);else calendarDate.setUTCDate(calendarDate.getUTCDate()+direction*(view==='week'?7:1));calendar();}$('cal-prev').onclick=()=>moveCalendar(-1);$('cal-next').onclick=()=>moveCalendar(1);$('new-event').onclick=()=>{prepareEvent();panel('events');};
  async function renderIncidents(){incidents=await api('/api/workspace/incidents?city_id='+state.city_id);$('incidents').innerHTML=incidents.map(i=>`<article class="card"><strong>${escape(i.name)}</strong><p>${escape(i.start)} / ${escape(i.end)}</p><p>${escape(i.description)}</p><a href="${escape(i.sources[0].url)}" target="_blank" rel="noopener">Fuente documentada</a> <button data-incident="${i.id}">Investigar</button></article>`).join('')||'<p class="hint">Sin acontecimientos documentados en el catálogo actual.</p>';$('incidents').querySelectorAll('[data-incident]').forEach(b=>b.onclick=()=>{const i=incidents.find(i=>i.id===b.dataset.incident);state.start=i.start;state.end=i.end;$('start').value=i.start;$('end').value=i.end;state.provider='power-daily';$('source').value='power-daily';variables();state.variable=i.related_variable;$('variable').value=state.variable;state.scale='daily';$('scale').value='daily';updateTime(i.start);range();});renderEvents();}
  function renderEvents(){eventMarkers.clearLayers();incidentMarkers.clearLayers();if($('incident-layer').checked){for(const incident of incidents){const c=cities.find(x=>x.id===incident.city_id);if(c)L.circleMarker([c.latitude,c.longitude],{radius:15,color:'#e5bb7b',fill:false,weight:2,dashArray:'4 4'}).bindTooltip(escape(incident.name)+' ? centroide de ciudad, sin extensión de impacto').addTo(incidentMarkers);}}$('time-markers').innerHTML=[...events.map(e=>({date:e.start.slice(0,10),name:e.name,city_id:e.city_id})),...($('incident-layer').checked?incidents:[]).map(i=>({date:i.start,name:i.name,city_id:i.city_id}))].map(e=>`<button data-date="${escape(e.date)}" data-city="${escape(e.city_id)}">⚑ ${escape(e.date)} · ${escape(e.name)}</button>`).join('');$('time-markers').querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selectCity(b.dataset.city);updateTime(b.dataset.date);});for(const e of events){const c=cities.find(c=>c.id===e.city_id);if(c)L.marker([c.latitude,c.longitude]).bindTooltip(escape(e.name)).addTo(eventMarkers);}calendar();}
  async function profile(){const id=state.city_id,result=await api('/api/workspace/profiles/'+id);if(id!==state.city_id)return;$('profile-title').textContent=result.city.name;$('profile-content').innerHTML=`<p>${escape(result.city.province)} · ${escape(result.city.region)}</p><p class="hint">${result.city.latitude.toFixed(5)}, ${result.city.longitude.toFixed(5)} · centroide GeoRef. Metadatos generales: se muestran solo campos con fuente verificada.</p><h2>Climatología mensual · 2000–2024</h2><p class="hint">${escape(result.method)}</p>`+Object.entries(result.climatology).map(([code,row])=>row.months?`<details><summary>${escape(row.name)} · ${escape(row.unit)}</summary><table><tr><th>Mes</th><th>Media</th><th>Desvío</th><th>Años</th></tr>${row.months.map(m=>`<tr><td>${m.month}</td><td>${number(m.mean)}</td><td>${number(m.std_dev)}</td><td>${m.count}</td></tr>`).join('')}</table></details>`:'').join('')+`<p class="hint">${result.limitations.map(escape).join(' ')}</p><a class="button" href="/fingerprint?city_id=${id}">Fingerprint y tendencias ↗</a> <button id="profile-plan">Planificar actividad</button>`;$('profile-plan').onclick=()=>{prepareEvent();panel('events');};
    const general=document.createElement('div');const elevation=result.general.altitude;const image=result.general.image;
 general.innerHTML=(image?'<figure><img style="max-width:100%;height:auto;border-radius:8px" src="'+escape(image.image_url)+'" alt="'+escape(image.caption||image.title)+'" loading="lazy"><figcaption class="hint">'+escape(image.caption||image.title)+' / '+escape(image.author)+' / '+escape(image.license)+' <a target="_blank" rel="noopener" href="'+escape(image.source_url)+'">Fuente y licencia</a>. Imagen ilustrativa; no condiciones actuales.</figcaption></figure>':'<p class="hint">Sin fotografia geolocalizada con licencia verificada.</p>')+(elevation?'<p>Elevacion del centroide: '+number(elevation.value)+' m</p><p class="hint">Copernicus DEM GLO-90 / Open-Meteo, pixel de 90 m. '+escape(elevation.limitation)+' <a href="'+escape(elevation.source_url)+'" target="_blank" rel="noopener">Fuente</a> / <a href="'+escape(elevation.citation)+'" target="_blank" rel="noopener">Citar Copernicus</a></p>':'')+'<p class="hint">Poblacion: sin una fuente censal incorporada.</p>';
 $('profile-content').prepend(general);
 if(radial){radial.destroy();radial=null;}const extra=document.createElement('div');extra.innerHTML='<h2>Perfil climatológico estandarizado</h2><button id="radial-profile">Mostrar ejes Z y metodología</button><div id="radial-result"></div><h2>Fingerprint de tendencias</h2><button id="trend-profile">Ver seis indicadores originales</button><div id="trend-profile-result"></div>'+'<h2>Otras dimensiones verificadas</h2>'+result.native_variables.map(v=>'<p class="hint">'+escape(v.provider+' · '+v.variable+' · '+v.unit)+'</p>').join('')+'<h2>Earth Connections</h2><button id="connections">Explorar asociaciones</button><div id="connections-result"></div><h2>Earth Twins</h2><button id="twins">Buscar ciudades similares</button><div id="twins-result"></div>';$('profile-content').append(extra);
    $('radial-profile').onclick=safe(async()=>{const data=await api('/api/workspace/profiles/'+id+'/climatology-fingerprint');if(id!==state.city_id)return;$('radial-result').innerHTML='<div class="chart-wrap"><canvas id="climate-radial"></canvas></div><p class="hint">'+escape(data.method)+' '+data.limitations.map(escape).join(' ')+'</p>';if(radial)radial.destroy();radial=new Chart($('climate-radial'),{type:'radar',data:{labels:data.axes.map(a=>a.variable),datasets:[{label:'Z climatológico · no salud ambiental',data:data.axes.map(a=>a.z_score),borderColor:'#65d4bd',backgroundColor:'#65d4bd22'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{tooltip:{callbacks:{label:item=>{const a=data.axes[item.dataIndex];return 'Z '+number(a.z_score)+' ? original '+number(a.raw_mean)+' '+a.unit;}}}},scales:{r:{ticks:{display:true},pointLabels:{color:'#8fa9b9',font:{size:9}}}}}});});
    $('trend-profile').onclick=safe(async()=>{const data=await api('/api/fingerprint/'+id);if(id!==state.city_id)return;$('trend-profile-result').innerHTML=data.results.map(r=>'<article class="card"><strong>'+escape(r.variable)+'</strong><p>'+escape(r.scientific_status||r.status||'provisional')+'</p><p>Cambio por década: '+number(r.statistics?.change_per_decade)+' '+escape(r.unit)+'</p></article>').join('')+'<p class="hint">Motor original; sin corrección de autocorrelación ni comparaciones múltiples. Cero descubrimientos confirmados.</p>';});
    $('connections').onclick=safe(async()=>{const data=await api('/api/workspace/profiles/'+id+'/connections');if(id!==state.city_id)return;$('connections-result').innerHTML=data.pairs.map(p=>'<article class="card"><p>'+escape(p.x.variable+' / '+p.y.variable)+'</p><p>r descriptivo: '+number(p.pearson_r_descriptive)+' · '+p.n+' meses pareados</p><p class="hint">'+data.limitations.map(escape).join(' ')+'</p></article>').join('')||'Sin pares compatibles.';});
    $('twins').onclick=safe(async()=>{const data=await api('/api/workspace/profiles/'+id+'/twins');if(id!==state.city_id)return;$('twins-result').innerHTML='<p class="hint">'+escape(data.method)+'</p>'+data.rows.slice(0,5).map(r=>'<p>'+escape(cities.find(c=>c.id===r.city_id)?.name||r.city_id)+' ? distancia '+number(r.distance)+'</p>').join('')+'<p class="hint">'+data.limitations.map(escape).join(' ')+'</p>';});}

  function prepareEvent(){const f=$('event-form');f.elements.id.value='';f.elements.start.value=state.date.slice(0,10)+'T10:00';f.elements.end.value=state.date.slice(0,10)+'T12:00';$('event-form-title').textContent='Planificar actividad';}
  function eventPayload(){const f=$('event-form').elements,prefs={};for(const k of ['min_temperature','max_temperature','max_probability','max_precipitation','max_wind','max_gust'])if(f[k].value!=='')prefs[k]=Number(f[k].value);prefs.require_official_alerts=f.require_official_alerts.checked;return {name:f.name.value,description:f.description.value,activity:f.activity.value,city_id:state.city_id,location_label:f.location_label.value,start:f.start.value+':00-03:00',end:f.end.value+':00-03:00',participants:+f.participants.value,transport:f.transport.value,outdoor:f.outdoor.checked,flexible_days:+f.flexible_days.value,flexible_hours:+f.flexible_hours.value,preferences:prefs,notifications:f.notifications.checked};}
  async function loadAccount(){const me=await api('/api/session');user=me.user;csrf=me.csrf_token;$('auth').hidden=!!user;$('account').hidden=!user;if(!user){events=[];$('badge').textContent='';$('events-list').textContent='';$('event-form').reset();$('notifications-list').textContent='Iniciá sesión en Mi espacio.';return;}$('account-name').textContent=user.username;events=await api('/api/events');$('events-list').innerHTML=events.map(e=>`<article class="card"><strong>${escape(e.name)}</strong><p>${escape(e.start)} · ${escape(e.status)}</p><div class="actions"><button data-edit="${e.id}">Editar</button><button data-cancel="${e.id}">Cancelar</button><button data-delete="${e.id}">Eliminar</button><button data-history="${e.id}">Evaluaciones</button><a class="button" href="/api/events/${e.id}/report.pdf">PDF</a></div></article>`).join('')||'<p>Sin eventos guardados.</p>';$('events-list').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const e=events.find(e=>e.id===b.dataset.edit);selectCity(e.city_id);const f=$('event-form').elements;for(const k of ['id','name','description','activity','participants','transport','flexible_days','flexible_hours','location_label'])f[k].value=e[k]??'';for(const k of ['start','end'])f[k].value=e[k].slice(0,16);f.outdoor.checked=e.outdoor;f.notifications.checked=e.notifications;for(const k of ['min_temperature','max_temperature','max_probability','max_precipitation','max_wind','max_gust'])f[k].value=e.preferences[k]??'';f.require_official_alerts.checked=e.preferences.require_official_alerts!==false;$('event-form-title').textContent='Editar / reprogramar evento';});$('events-list').querySelectorAll('[data-delete]').forEach(b=>b.onclick=safe(async()=>{if(confirm('¿Eliminar este evento y su historial?')){await api('/api/events/'+b.dataset.delete,{method:'DELETE'});await loadAccount();}}));$('events-list').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=safe(async()=>{await api('/api/events/'+b.dataset.cancel,{method:'PATCH',body:JSON.stringify({status:'cancelled'})});await loadAccount();}));$('events-list').querySelectorAll('[data-history]').forEach(b=>b.onclick=safe(async()=>{const rows=await api('/api/events/'+b.dataset.history+'/history');activeHistoryId=b.dataset.history;$('assessment').innerHTML=rows.map(r=>assessmentHTML(r.assessment)).join('')||'Sin ejecuciones de monitoreo.';const controls=document.createElement('div');controls.innerHTML='<h2>Revisiones del pronostico</h2><label>Variable<select id="version-variable"><option value="temperature_2m">Temperatura</option><option value="precipitation">Precipitacion</option><option value="wind_speed_10m">Viento</option><option value="wind_gusts_10m">Rafagas</option></select></label><div class="chart-wrap"><canvas id="version-chart"></canvas></div><p id="version-note" class="hint"></p>';$('assessment').prepend(controls);
 async function drawVersions(){const selectedId=activeHistoryId;const data=await api('/api/events/'+selectedId+'/forecast-history?variable='+$('version-variable').value);if(selectedId!==activeHistoryId)return;if(versionChart)versionChart.destroy();versionChart=new Chart($('version-chart'),{type:'line',data:{datasets:[{label:data.variable+' ('+data.unit+')',data:data.versions.map(v=>({x:Date.parse(v.fetched_at),y:v.value})),borderColor:'#65d4bd',pointRadius:4,spanGaps:false}]},options:{responsive:true,maintainAspectRatio:false,scales:{x:{type:'linear',ticks:{maxTicksLimit:4,callback:v=>new Date(v).toISOString().slice(0,16)}}}}});$('version-note').textContent='Hora pronosticada: '+data.valid_time+'. '+data.limitations.join(' ');}
 $('version-variable').onchange=safe(drawVersions);await drawVersions();}));notificationRows=await api('/api/notifications');$('badge').textContent=notificationRows.filter(n=>!n.read_at).length||'';$('notifications-list').innerHTML=notificationRows.map(n=>`<article class="card"><strong>${escape(n.title)}</strong><p>${escape(n.created_at)}</p><p>${escape(n.message)}</p><button data-read="${n.id}">${n.read_at?'Leída':'Marcar leída'}</button></article>`).join('')||'<p>Sin notificaciones.</p>';$('notifications-list').querySelectorAll('[data-read]').forEach(b=>b.onclick=safe(async()=>{await api('/api/notifications/'+b.dataset.read,{method:'PATCH',body:'{}'});await loadAccount();}));renderEvents();}
  $('auth-form').onsubmit=safe(async e=>{e.preventDefault();const f=$('auth-form').elements;const me=await api('/api/session/'+(e.submitter.name==='register'?'register':'login'),{method:'POST',body:JSON.stringify({username:f.username.value,password:f.password.value})});csrf=me.csrf_token;f.password.value='';await loadAccount();notice('Sesión iniciada. Los eventos son privados.');});$('logout').onclick=safe(async()=>{await api('/api/session/logout',{method:'POST',body:'{}'});await loadAccount();renderEvents();});
  $('event-form').onsubmit=safe(async e=>{e.preventDefault();if(!user){notice('Iniciá sesión para guardar un evento.',true);return;}const id=$('event-form').elements.id.value;await api('/api/events'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:JSON.stringify(eventPayload())});await loadAccount();notice('Evento guardado. El monitoreo se ejecuta mediante el comando independiente.');});
  function assessmentHTML(result){return `<article class="card"><strong>${escape(result.label||result.status)}</strong><p>${escape(result.generated_at||'')}</p>${(result.reasons||[]).map(r=>`<p>${escape(r.message||r)}</p>`).join('')}<p class="hint">${(result.limitations||[]).map(escape).join(' ')}</p></article>`;}
  $('preview-event').onclick=safe(async()=>{const result=await api('/api/events/preview',{method:'POST',body:JSON.stringify(eventPayload())});$('assessment').innerHTML=assessmentHTML(result.assessment)+'<h2>Fechas alternativas</h2>'+result.alternatives.map((a,i)=>`<article class="card"><p>${escape(a.start)} · ${escape(a.assessment.label)}</p><p>${escape(a.explanation)}</p><button data-reschedule="${i}">Usar esta fecha</button></article>`).join('');$('assessment').querySelectorAll('[data-reschedule]').forEach(b=>b.onclick=()=>{const a=result.alternatives[+b.dataset.reschedule];$('event-form').elements.start.value=a.start.slice(0,16);$('event-form').elements.end.value=a.end.slice(0,16);notice('Fecha aplicada al formulario. Guardá para confirmar la reprogramación.');});});
  async function impact(){const city=state.city_id,result=await api('/api/impact?city_id='+city);if(city!==state.city_id)return;$('impact-content').innerHTML=`<p class="eyebrow">${escape(result.status)}</p><p>${escape(result.summary)}</p>`+result.layers.map(l=>`<article class="card"><strong>${escape(l.name)}</strong><p>${escape(l.status)}</p><a href="${escape(l.source_url)}" target="_blank" rel="noopener">Fuente</a><p class="hint">${escape(l.limitation)}</p></article>`).join('');}
  function download(format){if(!record){notice('Seleccioná una serie con datos.',true);return;}const records=comparisonRecords.length>1?comparisonRecords:[record];const content=format==='json'?JSON.stringify(records.length>1?{kind:'independent_comparable_series',records}:record,null,2):'city_id,date,value,unit,provider,product,frequency,latitude,longitude,fetched_at\n'+records.flatMap(r=>r.series.map(p=>[r.location.id,p.date,p.value??'',r.unit,r.provider,r.product,r.frequency,r.location.latitude,r.location.longitude,r.fetched_at].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(','))).join('\n');const url=URL.createObjectURL(new Blob([content],{type:format==='json'?'application/json':'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='earthlens-'+state.city_id+'-'+state.variable+'.'+format;a.click();URL.revokeObjectURL(url);}
  $('export-json').onclick=()=>download('json');$('export-csv').onclick=()=>download('csv');$('report').onclick=()=>{const q=new URLSearchParams({city_id:state.city_id,variable:state.variable,provider:state.provider,start:state.start,end:state.end});if($('mode').value==='compare'){const second=selectedCities().find(c=>c.id!==state.city_id);if(second)q.set('city_b',second.id);}window.open('/api/workspace/report.pdf?'+q,'_blank','noopener');};$('theme').onclick=()=>document.body.classList.toggle('light');
  try{[cities,catalog]=await Promise.all([api('/api/cities'),api('/api/science/variables')]);$('city').innerHTML=cities.map(c=>`<option value="${c.id}">${escape(c.name)}</option>`).join('');if(!cities.some(c=>c.id===state.city_id))state.city_id=cities[0].id;if(state.scale==='daily'&&state.provider==='power'){state.provider='power-daily';}$('source').value=state.provider;variables();$('start').value=state.start;$('end').value=state.end;$('scale').value=state.scale;updateTime();selectCity(state.city_id);prepareEvent();panel(state.panel);await loadAccount();}catch(e){notice(e.message,true);}
